function getSlotPrice(
  startTime: string,
  pricePerHour: number | undefined,
  todayPricing: Record<string, number> | undefined,
): number {
  const defaultHalf = (pricePerHour ?? 0) / 2;
  return todayPricing?.[startTime] ?? defaultHalf;
}

