              <div key={slot} className={`grid border-b border-border/40 last:border-0 ${isNowRow ? "bg-primary/5" : ""}`} style={{ gridTemplateColumns: `64px repeat(7, 1fr)` }}>
                <div className={`px-2 py-1 flex items-center justify-end text-[10px] tabular-nums font-mono shrink-0 ${isNowRow ? "text-primary font-bold" : "text-muted-foreground"}`}>
                  {slot}
                </div>
                {days.map(day => {
                  const isToday = day === today;
                  const isPast = day < today || (isToday && slotMin + 30 <= nowMin);
                  const booking = weeklyBookings.find(b =>
                    b.courtId === court.id && b.date === day &&
                    toMin(b.startTime) <= slotMin && toMin(b.endTime) > slotMin
                  );
                  const blocked = !booking && weeklyBlockedSlots.find(bl =>
                    bl.courtId === court.id && bl.date === day &&
                    toMin(bl.startTime) <= slotMin && toMin(bl.endTime) > slotMin
                  );
                  return (
                    <div key={day} className="px-0.5 py-0.5">
                      {booking ? (
                        <div
                          onClick={() => onBookingClick(booking)}
                          className={`h-7 rounded text-[9px] font-medium border flex items-center justify-center cursor-pointer hover:opacity-75 transition-opacity ${
                            booking.status === "confirmed"
                              ? "bg-blue-500/15 text-blue-700 dark:text-blue-300 border-blue-400/30"
                              : booking.status === "pending"
                              ? "bg-amber-400/15 text-amber-700 dark:text-amber-300 border-amber-400/30"
                              : "bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40"
                          }`}
                        >
                          <span className="truncate px-1">{booking.customerName.split(" ")[0]}</span>
                        </div>
                      ) : blocked ? (
                        <div className="h-7 rounded text-[9px] font-medium border flex items-center justify-center bg-zinc-200 dark:bg-zinc-700/50 text-zinc-500 border-zinc-300/40">
                          <span className="truncate px-1">■</span>
                        </div>
                      ) : (
                        <div
                          onClick={() => !isPast && onFreeClick(day, slot)}
                          className={`h-7 rounded border border-dashed border-border/25 transition-colors ${isPast ? "opacity-20" : "cursor-pointer hover:bg-muted/40"}`}
                        />
                      )}
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>

        {/* Legend */}
        <div className="flex items-center gap-4 px-4 py-2.5 border-t border-border bg-muted/20 flex-wrap">
          <span className="text-[10px] text-muted-foreground font-semibold uppercase tracking-widest">Legenda:</span>
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 rounded-sm bg-blue-500/20 border border-blue-400/40" />
            <span className="text-[10px] text-muted-foreground">Patvirtinta</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 rounded-sm bg-amber-400/20 border border-amber-400/40" />
            <span className="text-[10px] text-muted-foreground">Laukiama</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 rounded-sm bg-zinc-200 dark:bg-zinc-700/60 border border-zinc-300/50" />
            <span className="text-[10px] text-muted-foreground">Užblokuota</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-3 rounded-sm border border-dashed border-border/60" />
            <span className="text-[10px] text-muted-foreground">Laisva (spustelėkite)</span>
          </div>
        </div>
      </div>
    </div>
  );
}

