130	
131	        <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
132	          <div className="bg-card border border-border rounded-2xl p-4">
133	            <div className="flex items-start justify-between mb-3">
134	              <p className="text-xs text-muted-foreground font-medium">Bendros pajamos</p>
135	              <div className="w-8 h-8 rounded-xl bg-emerald-500/10 flex items-center justify-center">
136	                <Euro className="h-4 w-4 text-emerald-500" />
137	              </div>
138	            </div>
139	            <p className="text-2xl font-bold">€{grossRevenue.toLocaleString("lt-LT", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
140	            <p className="text-xs text-muted-foreground mt-1">Šį mėnesį (su atšauktomis)</p>
141	          </div>
142	          <div className="bg-card border border-border rounded-2xl p-4">
143	            <div className="flex items-start justify-between mb-3">
144	              <p className="text-xs text-muted-foreground font-medium">Grąžinta klientams</p>
145	              <div className="w-8 h-8 rounded-xl bg-destructive/10 flex items-center justify-center">
146	                <Undo2 className="h-4 w-4 text-destructive" />
147	              </div>
148	            </div>
149	            <p className="text-2xl font-bold text-destructive">−€{refundedTotal.toLocaleString("lt-LT", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
150	            <p className="text-xs text-muted-foreground mt-1">Iš atšauktų rezervacijų</p>
