152	          <div className="bg-card border border-border rounded-2xl p-4">
153	            <div className="flex items-start justify-between mb-3">
154	              <p className="text-xs text-muted-foreground font-medium">Grynosios pajamos</p>
155	              <div className="w-8 h-8 rounded-xl bg-violet-500/10 flex items-center justify-center">
156	                <TrendingUp className="h-4 w-4 text-violet-500" />
157	              </div>
158	            </div>
159	            <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">€{netRevenue.toLocaleString("lt-LT", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
160	            <p className="text-xs text-muted-foreground mt-1">{dashData?.monthlyBookingCount ?? 0} rezervac. · Bendros − Grąžinta</p>
161	          </div>
162	        </div>
163	
164	        <div className="bg-card border border-border rounded-2xl overflow-hidden">
165	          <div className="flex items-center justify-between px-4 py-3 border-b border-border">
166	            <h2 className="font-semibold text-sm">Rezervacijų istorija</h2>
167	            <div className="flex gap-1">
168	              {(["all", "confirmed", "pending", "cancelled"] as const).map(s => (
169	                <button
170	                  key={s}
171	                  onClick={() => setStatusFilter(s)}
172	                  className={`px-2.5 py-1 rounded-lg text-xs font-medium transition-colors ${
173	                    statusFilter === s ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-muted"
174	                  }`}
175	                >
176	                  {s === "all" ? "Visi" : s === "confirmed" ? "Patvirtinta" : s === "pending" ? "Laukiama" : "Atšaukta"}
