179	            </div>
180	          </div>
181	
182	          {isLoading ? (
183	            <div className="p-4 space-y-3">
184	              {Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-14 rounded-xl" />)}
185	            </div>
186	          ) : filtered.length === 0 ? (
187	            <div className="flex flex-col items-center justify-center py-16">
188	              <CalendarDays className="h-10 w-10 text-muted-foreground/30 mb-3" />
189	              <p className="text-sm text-muted-foreground">Rezervacijų nėra</p>
190	            </div>
191	          ) : (
192	            <div className="divide-y divide-border/50">
193	              {filtered.map(b => {
