199	                      href={`${BASE_URL}/bookings/${b.id}`}
200	                      className="flex items-center gap-4 flex-1 min-w-0"
201	                    >
202	                      <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${
203	                        b.status === "confirmed" ? "bg-emerald-500/10" : b.status === "pending" ? "bg-amber-500/10" : "bg-destructive/10"
204	                      }`}>
205	                        {b.status === "confirmed"
206	                          ? <CheckCircle2 className="h-4 w-4 text-emerald-500" />
