227	                        variant={b.status === "confirmed" ? "default" : b.status === "pending" ? "secondary" : "destructive"}
228	                        className="text-[10px] px-1.5 py-0 mt-0.5"
229	                      >
230	                        {b.status === "confirmed" ? "Patvirtinta" : b.status === "pending" ? "Laukiama" : "Atšaukta"}
