271	}
272	
273	function ForceCancelDialog({
274	  booking,
275	  onClose,
276	  onSuccess,
277	}: {
278	  booking: BookingItem;
279	  onClose: () => void;
280	  onSuccess: (refundedEur: number) => void;
281	}) {
282	  type Preset = "full" | "half" | "none" | "custom";
283	  const [preset, setPreset] = useState<Preset>("full");
284	  const [customEur, setCustomEur] = useState<string>("");
285	  const [submitting, setSubmitting] = useState(false);
286	  const [serverError, setServerError] = useState<string | null>(null);
287	
288	  const totalPriceCents = Math.round(booking.totalPrice * 100);
289	
290	  const presetCents: number | null = (() => {
291	    if (preset === "full") return totalPriceCents;
292	    if (preset === "half") return Math.round(totalPriceCents * 0.5);
293	    if (preset === "none") return 0;
294	    return null;
295	  })();
296	
297	  const customCents: number | null = (() => {
298	    if (preset !== "custom") return null;
299	    const raw = customEur.replace(",", ".").trim();
300	    if (raw === "") return null;
301	    const v = Number(raw);
302	    if (!Number.isFinite(v)) return null;
303	    return Math.round(v * 100);
304	  })();
305	
306	  const finalCents = preset === "custom" ? customCents : presetCents;
307	
308	  const validationError: string | null = (() => {
309	    if (preset === "custom") {
310	      if (customEur.trim() === "") return "Įveskite sumą";
311	      if (customCents == null) return "Neteisinga suma";
312	      if (customCents < 0) return "Suma negali būti neigiama";
313	      if (customCents > totalPriceCents) {
314	        return `Suma negali viršyti €${booking.totalPrice.toFixed(2)}`;
315	      }
316	    }
317	    return null;
318	  })();
319	
320	  const canSubmit = !submitting && validationError == null && finalCents != null;
321	
322	  const submit = async () => {
323	    if (!canSubmit || finalCents == null) return;
324	    setSubmitting(true);
325	    setServerError(null);
326	    try {
327	      const resp = await customFetch<{ id: number; status: string; refundAmount: number }>(
328	        `${API_URL}/owner/bookings/${booking.id}/force-cancel`,
329	        {
330	          method: "POST",
331	          body: JSON.stringify({ refundAmountCents: finalCents }),
332	        },
333	      );
334	      const serverRefund = Number(resp?.refundAmount ?? finalCents / 100);
335	      onSuccess(serverRefund);
336	    } catch (err: unknown) {
337	      const msg = err instanceof Error ? err.message : "Nepavyko atšaukti rezervacijos";
338	      setServerError(msg);
339	    } finally {
340	      setSubmitting(false);
341	    }
342	  };
343	
344	  const PRESETS: { key: Preset; label: string; sub: string }[] = [
345	    { key: "full", label: "Pilnas (100%)", sub: `€${booking.totalPrice.toFixed(2)}` },
346	    { key: "half", label: "Dalinis (50%)", sub: `€${(booking.totalPrice / 2).toFixed(2)}` },
347	    { key: "none", label: "Be grąžinimo (0%)", sub: "€0.00" },
348	  ];
349	
350	  return (
351	    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
352	      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
353	      <div className="relative bg-card border border-border rounded-2xl shadow-2xl w-full max-w-md p-6">
354	        <button
355	          onClick={onClose}
356	          className="absolute top-4 right-4 p-1 rounded hover:bg-muted transition-colors"
357	          aria-label="Uždaryti"
358	        >
359	          <X className="h-4 w-4" />
360	        </button>
361	
362	        <div className="flex items-center gap-2 mb-1">
363	          <AlertTriangle className="h-5 w-5 text-destructive" />
364	          <h2 className="text-lg font-bold">Priverstinis atšaukimas</h2>
365	        </div>
366	        <p className="text-xs text-muted-foreground mb-4">
367	          Apeina 24h/48h taisyklę. Grąžinimas bus išsiųstas iš karto.
368	        </p>
369	
370	        <div className="bg-muted/40 rounded-xl px-3 py-2 mb-4 text-sm">
371	          <p className="font-medium">{booking.customerName}</p>
372	          <p className="text-xs text-muted-foreground">
373	            {booking.courtName ?? `Kortas #${booking.courtId}`} · {booking.date} {booking.startTime}–{booking.endTime}
374	          </p>
375	          <p className="text-xs mt-1">Sumokėta: <span className="font-semibold">€{booking.totalPrice.toFixed(2)}</span></p>
376	        </div>
377	
378	        <div className="space-y-2 mb-3">
379	          {PRESETS.map(p => (
380	            <button
381	              key={p.key}
382	              type="button"
383	              onClick={() => { setPreset(p.key); setServerError(null); }}
384	              className={`w-full flex items-center justify-between px-3 py-2.5 rounded-lg border text-left text-sm transition-colors ${
385	                preset === p.key
386	                  ? "border-primary bg-primary/10 text-foreground"
387	                  : "border-border hover:bg-muted/40 text-muted-foreground"
388	              }`}
389	            >
390	              <span className="font-medium">{p.label}</span>
391	              <span className="text-xs tabular-nums">{p.sub}</span>
392	            </button>
393	          ))}
394	
395	          <div
396	            className={`w-full px-3 py-2.5 rounded-lg border transition-colors ${
397	              preset === "custom" ? "border-primary bg-primary/10" : "border-border"
398	            }`}
399	          >
400	            <button
401	              type="button"
402	              onClick={() => { setPreset("custom"); setServerError(null); }}
403	              className="w-full flex items-center justify-between text-left text-sm mb-1"
404	            >
405	              <span className={`font-medium ${preset === "custom" ? "" : "text-muted-foreground"}`}>Kita suma</span>
406	              <span className="text-xs text-muted-foreground">Iki €{booking.totalPrice.toFixed(2)}</span>
407	            </button>
408	            {preset === "custom" && (
409	              <div className="flex items-center gap-2 mt-1">
410	                <span className="text-sm text-muted-foreground">€</span>
411	                <input
412	                  type="text"
413	                  inputMode="decimal"
414	                  autoFocus
415	                  value={customEur}
416	                  onChange={e => { setCustomEur(e.target.value); setServerError(null); }}
417	                  placeholder="0,00"
418	                  className="flex-1 bg-background border border-border rounded-md px-2 py-1.5 text-sm tabular-nums focus:outline-none focus:ring-1 focus:ring-primary"
419	                />
420	              </div>
421	            )}
422	          </div>
423	        </div>
424	
425	        {(validationError || serverError) && (
426	          <p className="text-xs text-destructive mb-3">{validationError ?? serverError}</p>
427	        )}
428	
429	        <div className="flex gap-2">
430	          <Button variant="outline" className="flex-1" onClick={onClose} disabled={submitting}>
431	            Atšaukti
432	          </Button>
433	          <Button
434	            variant="destructive"
435	            className="flex-1"
436	            onClick={submit}
437	            disabled={!canSubmit}
438	          >
439	            {submitting ? "Atšaukiama…" : "Patvirtinti"}
440	          </Button>
441	        </div>
442	      </div>
443	    </div>
444	  );
445	}
