13	/**
14	 * GET /api/owner/bookings
15	 *
16	 * Facility-wide bookings list for owners/admins. Returns every booking on a
17	 * court that belongs to a facility the caller owns. Used by the owner payments
18	 * dashboard. Players use GET /api/bookings for their personal "my bookings"
19	 * view.
20	 */
21	router.get("/owner/bookings", requireOwner, async (req, res): Promise<void> => {
22	  const userId = getCurrentUserId(req)!;
23	
24	  const rows = await db
25	    .select({ booking: bookingsTable, courtName: courtsTable.name })
26	    .from(bookingsTable)
27	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
28	    .where(
29	      inArray(
30	        courtsTable.facilityId,
31	        db.select({ id: facilitiesTable.id })
32	          .from(facilitiesTable)
33	          .where(eq(facilitiesTable.ownerUserId, userId)),
34	      ),
35	    );
36	
37	  res.json(rows.map(r => ({
38	    id: r.booking.id,
39	    courtId: r.booking.courtId,
40	    courtName: r.courtName ?? undefined,
41	    customerName: r.booking.customerName,
42	    customerEmail: r.booking.customerEmail,
43	    customerPhone: r.booking.customerPhone ?? undefined,
44	    date: r.booking.date,
45	    startTime: r.booking.startTime,
46	    endTime: r.booking.endTime,
47	    totalPrice: Number(r.booking.totalPrice),
48	    refundAmount: Number(r.booking.refundAmount ?? 0),
49	    status: r.booking.status,
50	    isSplit: r.booking.isSplit,
51	    totalSlots: r.booking.totalSlots ?? undefined,
52	    pricePerSlot: r.booking.pricePerSlot != null ? Number(r.booking.pricePerSlot) : undefined,
53	    rentedItems: r.booking.rentedItems ?? undefined,
54	    stripeSessionId: r.booking.stripeSessionId ?? undefined,
55	    stripePaymentIntentId: r.booking.stripePaymentIntentId ?? undefined,
56	    stripeRefundId: r.booking.stripeRefundId ?? undefined,
57	    createdAt: r.booking.createdAt,
58	  })));
59	});
60	
61	const ForceCancelBody = z.object({
62	  refundAmountCents: z.number().int().min(0),
63	});
64	
65	/**
66	 * POST /api/owner/bookings/:id/force-cancel
67	 *
68	 * Owner manual override. Bypasses the 24h/48h cancellation policy and accepts
69	 * a custom refund amount in cents (0..totalPriceCents). Requires the caller to
70	 * own the court (directly via courts.ownerUserId, or transitively via the
71	 * facility's ownerUserId).
72	 *
73	 * Mirrors DELETE /bookings/:id but with no time restriction and a caller-supplied
74	 * refund amount. Issues a Stripe refund (idempotent, distinct key from the regular
75	 * cancel) and frees the timeslot by transitioning status to "cancelled".
76	 */
77	router.post("/owner/bookings/:id/force-cancel", requireAuth, async (req, res): Promise<void> => {
78	  const id = Number(req.params.id);
79	  if (!Number.isInteger(id) || id <= 0) {
80	    res.status(400).json({ error: "Invalid booking id" });
81	    return;
82	  }
83	
84	  const parsed = ForceCancelBody.safeParse(req.body);
85	  if (!parsed.success) {
86	    res.status(400).json({ error: parsed.error.message });
87	    return;
88	  }
89	
90	  const userId = getCurrentUserId(req)!;
91	
92	  const rows = await db
93	    .select({
94	      booking: bookingsTable,
95	      courtOwnerUserId: facilitiesTable.ownerUserId,
96	      courtFacilityId: courtsTable.facilityId,
97	      courtName: courtsTable.name,
98	      ownerName: facilitiesTable.name,
99	      ownerEmail: facilitiesTable.email,
100	    })
101	    .from(bookingsTable)
102	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
103	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
104	    .where(eq(bookingsTable.id, id));
105	
106	  if (!rows[0]) {
107	    res.status(404).json({ error: "Booking not found" });
108	    return;
109	  }
110	
111	  const { booking, courtOwnerUserId, courtFacilityId, courtName, ownerName, ownerEmail } = rows[0];
112	
113	  // Ownership check: caller must own the facility.
114	  const isOwner = courtOwnerUserId === userId;
115	  if (!isOwner) {
116	    res.status(403).json({ error: "Forbidden" });
117	    return;
118	  }
119	
120	  if (booking.status === "cancelled") {
121	    res.status(409).json({ error: "Booking is already cancelled" });
122	    return;
