router.get("/owner/bookings", requireOwner, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const scopedFacilityId = req.query.facilityId ? Number(req.query.facilityId) : undefined;

  // Resolve facility IDs the caller owns, optionally scoped to one.
  const ownedFacilities = await db
    .select({ id: facilitiesTable.id })
    .from(facilitiesTable)
    .where(eq(facilitiesTable.ownerUserId, userId));
  const ownedIds = ownedFacilities.map(f => f.id);

  if (ownedIds.length === 0) { res.json([]); return; }

  if (scopedFacilityId !== undefined && !ownedIds.includes(scopedFacilityId)) {
    res.status(403).json({ error: "Forbidden" }); return;
  }

  const facilityFilter = scopedFacilityId !== undefined
    ? eq(courtsTable.facilityId, scopedFacilityId)
    : inArray(courtsTable.facilityId, ownedIds);

  const rows = await db
    .select({ booking: bookingsTable, courtName: courtsTable.name })
    .from(bookingsTable)
    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
    .where(facilityFilter)
    .orderBy(bookingsTable.createdAt);

