import Holidays from "date-holidays";
import { db, courtPricingTable, courtPriceOverridesTable, courtPricingRulesTable } from "@workspace/db";
import { and, eq } from "drizzle-orm";

const hd = new Holidays("LT");

/** Resolve the price (in EUR, per 30-min slot) for a single slot on a specific date. */
export async function resolvePriceForSlot(
  courtId: number,
  date: string,          // YYYY-MM-DD
  startTime: string,     // HH:MM
  defaultSlotPrice: number
): Promise<number> {
  const slotDate = new Date(`${date}T12:00:00`);
  const dayOfWeek = slotDate.getDay();

  const [overrides, weeklyEntries, rules] = await Promise.all([
    db.select()
      .from(courtPriceOverridesTable)
      .where(and(
        eq(courtPriceOverridesTable.courtId, courtId),
        eq(courtPriceOverridesTable.date, date),
        eq(courtPriceOverridesTable.startTime, startTime),
      )),
    db.select()
      .from(courtPricingTable)
      .where(and(
        eq(courtPricingTable.courtId, courtId),
        eq(courtPricingTable.dayOfWeek, dayOfWeek),
        eq(courtPricingTable.startTime, startTime),
      )),
    db.select()
      .from(courtPricingRulesTable)
      .where(and(
        eq(courtPricingRulesTable.courtId, courtId),
        eq(courtPricingRulesTable.type, "holiday"),
      )),
  ]);

  // 1. Date-specific override (highest priority)
  if (overrides.length > 0) return Number(overrides[0].price);

  // 2. Holiday rule — only when the date is a public holiday
  const isHoliday = !!hd.isHoliday(slotDate);
  if (isHoliday && rules.length > 0) return Number(rules[0].price);

  // 3. Weekly recurring template
  if (weeklyEntries.length > 0) return Number(weeklyEntries[0].price);

  // 4. Default fallback
  return defaultSlotPrice;
}

/**
 * Build a price map for all slots in a day, batching the DB calls once
 * instead of per-slot. Used in the availability endpoint.
 */
export async function buildDayPriceMap(
  courtId: number,
  date: string,
  defaultSlotPrice: number
): Promise<{ priceMap: Map<string, number>; isHoliday: boolean }> {
  try {
    return await _buildDayPriceMap(courtId, date, defaultSlotPrice);
  } catch {
    // Fallback if pricing tables aren't available yet
    return { priceMap: new Map(), isHoliday: false };
  }
}

async function _buildDayPriceMap(
  courtId: number,
  date: string,
  defaultSlotPrice: number
): Promise<{ priceMap: Map<string, number>; isHoliday: boolean }> {
  const slotDate = new Date(`${date}T12:00:00`);
  const dayOfWeek = slotDate.getDay();
  const isHolidayDay = !!hd.isHoliday(slotDate);

  const [weeklyEntries, dateOverrides, holidayRules] = await Promise.all([
    db.select()
      .from(courtPricingTable)
      .where(and(
        eq(courtPricingTable.courtId, courtId),
        eq(courtPricingTable.dayOfWeek, dayOfWeek),
      )),
    db.select()
      .from(courtPriceOverridesTable)
      .where(and(
        eq(courtPriceOverridesTable.courtId, courtId),
        eq(courtPriceOverridesTable.date, date),
      )),
    db.select()
      .from(courtPricingRulesTable)
      .where(and(
        eq(courtPricingRulesTable.courtId, courtId),
        eq(courtPricingRulesTable.type, "holiday"),
      )),
  ]);

  const weeklyMap = new Map(weeklyEntries.map(e => [e.startTime, Number(e.price)]));
  const overrideMap = new Map(dateOverrides.map(e => [e.startTime, Number(e.price)]));

  // Per-slot holiday prices (startTime set) and optional catch-all (startTime null)
  const holidaySlotMap = new Map<string, number>();
  let holidayFallback: number | null = null;
  for (const r of holidayRules) {
    if (r.startTime) {
      holidaySlotMap.set(r.startTime, Number(r.price));
    } else {
      holidayFallback = Number(r.price);
    }
  }

  // Waterfall: date override > holiday (slot-specific then fallback) > weekly > default
  const priceMap = new Map<string, number>();
  const allTimes = new Set([...weeklyMap.keys(), ...overrideMap.keys(), ...holidaySlotMap.keys()]);

  // Pre-generate all 30-min slots 06:00-23:00 so every slot has an entry
  for (let h = 6; h < 23; h++) {
    for (const m of [0, 30]) {
      const t = `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
      allTimes.add(t);
    }
  }

  for (const t of allTimes) {
    if (overrideMap.has(t)) {
      priceMap.set(t, overrideMap.get(t)!);
    } else if (isHolidayDay && holidaySlotMap.has(t)) {
      priceMap.set(t, holidaySlotMap.get(t)!);
    } else if (isHolidayDay && holidayFallback !== null) {
      priceMap.set(t, holidayFallback);
    } else if (weeklyMap.has(t)) {
      priceMap.set(t, weeklyMap.get(t)!);
    } else {
      priceMap.set(t, defaultSlotPrice);
    }
  }

  return { priceMap, isHoliday: isHolidayDay };
}

import { Router, type IRouter } from "express";
import { eq, and, inArray, ne } from "drizzle-orm";
import { z } from "zod";
import { db, bookingsTable, courtsTable, facilitiesTable } from "@workspace/db";
import { requireAuth, requireOwner, getCurrentUserId } from "../lib/auth";
import { sendNotification } from "../lib/notify";
import { sendCustomerCancellationEmail } from "../lib/email";
import { getUncachableStripeClient } from "../stripeClient";
import { logger } from "../lib/logger";

const router: IRouter = Router();

/**
 * GET /api/owner/bookings
 *
 * Facility-wide bookings list for owners/admins. Returns every booking on a
 * court that belongs to a facility the caller owns. Used by the owner payments
 * dashboard. Players use GET /api/bookings for their personal "my bookings"
 * view.
 */
router.get("/owner/bookings", requireOwner, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const scopedFacilityId = req.query.facilityId ? Number(req.query.facilityId) : undefined;

  // Resolve facility IDs the caller owns, optionally scoped to one.
  const ownedFacilities = await db
    .select({ id: facilitiesTable.id })
    .from(facilitiesTable)
    .where(eq(facilitiesTable.ownerUserId, userId));
  const ownedIds = ownedFacilities.map(f => f.id);

  if (ownedIds.length === 0) { res.json([]); return; }

  if (scopedFacilityId !== undefined && !ownedIds.includes(scopedFacilityId)) {
    res.status(403).json({ error: "Forbidden" }); return;
  }

  const facilityFilter = scopedFacilityId !== undefined
    ? eq(courtsTable.facilityId, scopedFacilityId)
    : inArray(courtsTable.facilityId, ownedIds);

  const rows = await db
    .select({ booking: bookingsTable, courtName: courtsTable.name })
    .from(bookingsTable)
    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
    .where(facilityFilter)
    .orderBy(bookingsTable.createdAt);

  res.json(rows.map(r => ({
    id: r.booking.id,
    courtId: r.booking.courtId,
    courtName: r.courtName ?? undefined,
    customerName: r.booking.customerName,
    customerEmail: r.booking.customerEmail,
    customerPhone: r.booking.customerPhone ?? undefined,
    date: r.booking.date,
    startTime: r.booking.startTime,
    endTime: r.booking.endTime,
    totalPrice: Number(r.booking.totalPrice),
    refundAmount: Number(r.booking.refundAmount ?? 0),
    status: r.booking.status,
    isSplit: r.booking.isSplit,
    totalSlots: r.booking.totalSlots ?? undefined,
    pricePerSlot: r.booking.pricePerSlot != null ? Number(r.booking.pricePerSlot) : undefined,
    rentedItems: r.booking.rentedItems ?? undefined,
    stripeSessionId: r.booking.stripeSessionId ?? undefined,
    stripePaymentIntentId: r.booking.stripePaymentIntentId ?? undefined,
    stripeRefundId: r.booking.stripeRefundId ?? undefined,
    createdAt: r.booking.createdAt,
  })));
});

const ForceCancelBody = z.object({
  refundAmountCents: z.number().int().min(0),
});

/**
 * POST /api/owner/bookings/:id/force-cancel
 *
 * Owner manual override. Bypasses the 24h/48h cancellation policy and accepts
 * a custom refund amount in cents (0..totalPriceCents). Requires the caller to
 * own the court (directly via courts.ownerUserId, or transitively via the
 * facility's ownerUserId).
 *
 * Mirrors DELETE /bookings/:id but with no time restriction and a caller-supplied
 * refund amount. Issues a Stripe refund (idempotent, distinct key from the regular
 * cancel) and frees the timeslot by transitioning status to "cancelled".
 */
router.post("/owner/bookings/:id/force-cancel", requireAuth, async (req, res): Promise<void> => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    res.status(400).json({ error: "Invalid booking id" });
    return;
  }

  const parsed = ForceCancelBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.message });
    return;
  }

  const userId = getCurrentUserId(req)!;

  const rows = await db
    .select({
      booking: bookingsTable,
      courtOwnerUserId: facilitiesTable.ownerUserId,
      courtFacilityId: courtsTable.facilityId,
      courtName: courtsTable.name,
      ownerName: facilitiesTable.name,
      ownerEmail: facilitiesTable.email,
    })
    .from(bookingsTable)
    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
    .where(eq(bookingsTable.id, id));

  if (!rows[0]) {
    res.status(404).json({ error: "Booking not found" });
    return;
  }

  const { booking, courtOwnerUserId, courtFacilityId, courtName, ownerName, ownerEmail } = rows[0];

  // Ownership check: caller must own the facility.
  const isOwner = courtOwnerUserId === userId;
  if (!isOwner) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  if (booking.status === "cancelled") {
    res.status(409).json({ error: "Booking is already cancelled" });
    return;
  }

  // Validate refund amount: must not exceed the original totalPrice.
  const totalPriceEur = Number(booking.totalPrice);
  const totalPriceCents = Math.round(totalPriceEur * 100);
  const refundCents = parsed.data.refundAmountCents;
  if (refundCents > totalPriceCents) {
    res.status(400).json({
      error: `Refund amount (${(refundCents / 100).toFixed(2)} €) exceeds booking total (${totalPriceEur.toFixed(2)} €)`,
      code: "REFUND_EXCEEDS_TOTAL",
    });
    return;
  }
  const refundEur = refundCents / 100;

  // Atomic compare-and-set on status to prevent double-refund races with the
  // regular cancel route.
  const claimed = await db
    .update(bookingsTable)
    .set({ status: "cancelled" })
    .where(and(eq(bookingsTable.id, id), ne(bookingsTable.status, "cancelled")))
    .returning();

  if (claimed.length === 0) {
    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, id));
    res.json({
      id: current.id,
      status: current.status,
      refundAmount: Number(current.refundAmount ?? 0),
    });
    return;
  }

  // Issue Stripe refund if applicable. Use a distinct idempotency key from the
  // regular cancel route so an owner override after a customer self-cancel
  // doesn't get suppressed by Stripe's idempotency cache.
  let stripeRefundId: string | null = null;
  if (
    refundCents > 0 &&
    booking.stripePaymentIntentId &&
    !booking.stripePaymentIntentId.startsWith("mock_")
  ) {
    try {
      const stripe = await getUncachableStripeClient();
      const refund = await stripe.refunds.create(
        {
          payment_intent: booking.stripePaymentIntentId,
          amount: refundCents,
          reason: "requested_by_customer",
        },
        { idempotencyKey: `force-cancel-booking-${id}` },
      );
      stripeRefundId = refund.id;
      logger.info(
        { bookingId: id, refundId: refund.id, amount: refundEur, actor: userId },
        "Stripe force-cancel refund issued",
      );
    } catch (err) {
      logger.error({ err, bookingId: id }, "Stripe force-cancel refund failed");
      await db
        .update(bookingsTable)
        .set({ status: booking.status })
        .where(eq(bookingsTable.id, id));
      res.status(502).json({ error: "Refund failed at payment provider" });
      return;
    }
  }

  const [updated] = await db
    .update(bookingsTable)
    .set({
      refundAmount: String(refundEur),
      stripeRefundId,
    })
    .where(eq(bookingsTable.id, id))
    .returning();

  // Notifications (fire-and-forget, never block the response).
  const displayCourtName = courtName ?? "Kortas";
  const dateStr = typeof booking.date === "string" ? booking.date : String(booking.date);

  // Notify the booker (unless the owner force-cancelled their own booking).
  if (booking.bookerUserId && booking.bookerUserId !== userId) {
    sendNotification(
      booking.bookerUserId,
      "booking_cancelled",
      `Rezervacija atšaukta — ${displayCourtName}`,
      refundEur > 0
        ? `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko. Grąžinta: ${refundEur.toFixed(2)} €.`
        : `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko.`,
      "/bookings",
    ).catch((err) => logger.error({ err, bookingId: id }, "force-cancel booker notification failed"));
  }

  // Email customer with refund details.
  if (booking.customerEmail) {
    sendCustomerCancellationEmail({
      customerName: booking.customerName,
      customerEmail: booking.customerEmail,
      courtName: displayCourtName,
      date: booking.date,
      startTime: booking.startTime,
      endTime: booking.endTime,
      totalPrice: totalPriceEur,
      refundAmount: refundEur,
      bookingId: id,
    }).catch((err) => logger.error({ err, bookingId: id }, "force-cancel customer email failed"));
  }

  // No notification/email to the owner — they triggered this themselves.
  // Reference ownerName/ownerEmail to satisfy noUnusedLocals while preserving
  // them in the join (also lets us log who the owner was for audit).
  void ownerName;
  void ownerEmail;

  res.json({
    id: updated.id,
    status: updated.status,
    refundAmount: Number(updated.refundAmount ?? 0),
    stripeRefundId: updated.stripeRefundId ?? null,
  });
});

export default router;

import { useParams, useLocation } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { customFetch } from "@workspace/api-client-react";
import { OwnerLayout, useFacilityId } from "@/components/owner-layout";
import { BackButton } from "@/components/back-button";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import {
  Calendar, Clock, User, Mail, Phone, Building2,
  CreditCard, FileText, AlertTriangle,
} from "lucide-react";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

interface BookingDetail {
  id: number;
  courtId: number;
  courtName?: string;
  courtSport?: string;
  facilityName?: string;
  customerName: string;
  customerEmail: string;
  customerPhone?: string | null;
  bookerUserId?: string | null;
  date: string;
  startTime: string;
  endTime: string;
  totalPrice: number;
  refundAmount?: number | null;
  status: string;
  notes?: string | null;
  rentedItems?: string | null;
  createdAt: string;
  isSplit?: boolean;
  totalSlots?: number;
  pricePerSlot?: number;
}

const STATUS_LABELS: Record<string, string> = {
  confirmed: "Patvirtinta",
  pending: "Laukiama",
  cancelled: "Atšaukta",
  blocked: "Užblokuota",
  awaiting_players: "Laukiama žaidėjų",
};

const STATUS_VARIANTS: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  confirmed: "default",
  pending: "secondary",
  cancelled: "destructive",
  blocked: "outline",
  awaiting_players: "secondary",
};

function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex justify-between items-start gap-4 py-2.5">
      <span className="text-sm text-muted-foreground shrink-0">{label}</span>
      <span className="text-sm font-medium text-right">{children}</span>
    </div>
  );
}

export default function OwnerBookingDetail() {
  const { id } = useParams<{ id: string }>();
  const facilityId = useFacilityId();
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: booking, isLoading, error } = useQuery<BookingDetail>({
    queryKey: ["owner-booking", id],
    queryFn: () => customFetch<BookingDetail>(`${API}/bookings/${id}`),
    enabled: !!id,
  });

  const cancelMutation = useMutation({
    mutationFn: () => customFetch(`${API}/bookings/${id}`, { method: "DELETE" }),
    onSuccess: () => {
      toast({ title: "Rezervacija atšaukta" });
      queryClient.invalidateQueries({ queryKey: ["owner-booking", id] });
      queryClient.invalidateQueries({ queryKey: ["owner-dashboard"] });
    },
    onError: (e: any) =>
      toast({ title: "Klaida", description: e?.data?.error || e?.message || "Nepavyko atšaukti", variant: "destructive" }),
  });

  const canCancel = booking && ["confirmed", "pending", "blocked", "awaiting_players"].includes(booking.status);
  const isGuest = booking && !booking.bookerUserId;
  const note = booking?.rentedItems ?? booking?.notes ?? null;

  return (
    <OwnerLayout facilityId={facilityId} title="Rezervacija">
      <div className="p-4 md:p-6 max-w-2xl mx-auto space-y-5">
        <BackButton label="Atgal" historyBack fallbackTo="/owner/dashboard" />

        {isLoading ? (
          <div className="space-y-3">
            <Skeleton className="h-8 w-48 rounded-lg" />
            <Skeleton className="h-64 rounded-2xl" />
          </div>
        ) : error || !booking ? (
          <div className="flex flex-col items-center justify-center py-16 text-center">
            <AlertTriangle className="h-10 w-10 text-muted-foreground/30 mb-3" />
            <p className="text-sm text-muted-foreground">Rezervacija nerasta arba prieiga uždrausta.</p>
          </div>
        ) : (
          <>
            <div className="flex items-start justify-between gap-3">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Rezervacija #{booking.id}</h1>
                {booking.courtName && (
                  <p className="text-sm text-muted-foreground mt-0.5">{booking.courtName}</p>
                )}
              </div>
              <Badge variant={STATUS_VARIANTS[booking.status] ?? "outline"} className="mt-1 shrink-0">
                {STATUS_LABELS[booking.status] ?? booking.status}
              </Badge>
            </div>

            {/* Customer info */}
            <div className="bg-card border border-border rounded-2xl p-4">
              <h2 className="text-sm font-semibold mb-1 flex items-center gap-2">
                <User className="h-4 w-4 text-muted-foreground" />
                Klientas
              </h2>
              <Separator className="my-2" />
              <Row label="Vardas">{booking.customerName}</Row>
              {booking.customerEmail && !booking.customerEmail.startsWith("manual-") && (
                <Row label="El. paštas">
                  <a href={`mailto:${booking.customerEmail}`} className="text-primary hover:underline">
                    {booking.customerEmail}
                  </a>
                </Row>
              )}
              {booking.customerPhone && (
                <Row label="Telefonas">
                  <a href={`tel:${booking.customerPhone}`} className="text-primary hover:underline">
                    {booking.customerPhone}
                  </a>
                </Row>
              )}
              {isGuest && (
                <p className="text-xs text-muted-foreground mt-2 pt-2 border-t border-border/40">Svečio rezervacija (be paskyros)</p>
              )}
            </div>

            {/* Booking info */}
            <div className="bg-card border border-border rounded-2xl p-4">
              <h2 className="text-sm font-semibold mb-1 flex items-center gap-2">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                Rezervacijos detalės
              </h2>
              <Separator className="my-2" />
              {booking.facilityName && <Row label="Objektas">{booking.facilityName}</Row>}
              {booking.courtName && <Row label="Kortas">{booking.courtName}</Row>}
              <Row label="Data">
                {new Date(booking.date + "T12:00:00").toLocaleDateString("lt-LT", {
                  weekday: "long", year: "numeric", month: "long", day: "numeric",
                })}
              </Row>
              <Row label="Laikas">
                <span className="flex items-center gap-1">
                  <Clock className="h-3.5 w-3.5 text-muted-foreground" />
                  {booking.startTime} – {booking.endTime}
                </span>
              </Row>
              <Row label="Sukurta">
                {new Date(booking.createdAt).toLocaleDateString("lt-LT", {
                  year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit",
                })}
              </Row>
            </div>

            {/* Payment info */}
            <div className="bg-card border border-border rounded-2xl p-4">
              <h2 className="text-sm font-semibold mb-1 flex items-center gap-2">
                <CreditCard className="h-4 w-4 text-muted-foreground" />
                Mokėjimas
              </h2>
              <Separator className="my-2" />
              {booking.isSplit ? (
                <>
                  <Row label="Tipas">Pasidalintas mokėjimas</Row>
                  <Row label="Dalyviai">{booking.totalSlots ?? "—"}</Row>
                  <Row label="Kaina / dalyvis">€{((booking.pricePerSlot ?? 0)).toFixed(2)}</Row>
                </>
              ) : null}
              <Row label="Bendra suma">
                <span className="text-base font-bold">€{booking.totalPrice.toFixed(2)}</span>
              </Row>
              {booking.refundAmount != null && booking.refundAmount > 0 && (
                <Row label="Grąžinta">
                  <span className="text-destructive">−€{booking.refundAmount.toFixed(2)}</span>
                </Row>
              )}
            </div>

            {/* Notes */}
            {note && (
              <div className="bg-card border border-border rounded-2xl p-4">
                <h2 className="text-sm font-semibold mb-1 flex items-center gap-2">
                  <FileText className="h-4 w-4 text-muted-foreground" />
                  Pastaba
                </h2>
                <Separator className="my-2" />
                <p className="text-sm text-foreground">{note.startsWith("Pastaba: ") ? note.slice(9) : note}</p>
              </div>
            )}

            {/* Actions */}
            {canCancel && (
              <Button
                variant="destructive"
                className="w-full"
                disabled={cancelMutation.isPending}
                onClick={() => cancelMutation.mutate()}
              >
                {cancelMutation.isPending
                  ? "Atšaukiama…"
                  : booking.status === "blocked"
                  ? "Atblokuoti laiką"
                  : "Atšaukti rezervaciją"}
              </Button>
            )}
          </>
        )}
      </div>
    </OwnerLayout>
  );
}

